    correction: [{"quoi":"البعد بين المركزين","math":"<span dir=\"ltr\" class=\"expr\">AB = 6</span>"},{"quoi":"الشعاعان","math":"<span dir=\"ltr\" class=\"expr\">r = 3</span>  و  <span dir=\"ltr\" class=\"expr\">r' = 3</span>"},{"quoi":"المجموع و الفرق","math":"<span dir=\"ltr\" class=\"expr\">r + r' = 6</span>  و  |<span dir=\"ltr\" class=\"expr\">r - r'</span>| <span dir=\"ltr\" class=\"expr\">= 0</span>"},{"quoi":"القاعدة","math":"إذا كان البعد بين المركزين يساوي مجموع الشعاعين فالدائرتان متماستان خارجيا"},{"quoi":"النتيجة","math":"الدائرتان متماستان خارجيا"}],
