    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr\">(d3)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[BC]</span>  و  <span dir=\"ltr\" class=\"expr\">MA = MB</span>  و  <span dir=\"ltr\" class=\"expr\">MA = MC</span>"},{"quoi":"الاختيار","math":"المطلوب : إثبات الانتماء. نختار تعدّي التساوي لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr\">: MB = MA</span>  و  <span dir=\"ltr\" class=\"expr\">MA = MC.</span> و لماذا لا عموديان على نفس المستقيم ؟ لأنّها تحتاج مستقيمين عموديين على نفس المستقيم، و لا نملك إلّا تعامدا واحدا على الأكثر."},{"quoi":"القاعدة","math":"إذا كان طولان يساويان طولا ثالثا فهما متساويان"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr\">MB = MA</span>  و  <span dir=\"ltr\" class=\"expr\">MA = MC</span>  إذن  <span dir=\"ltr\" class=\"expr\">MB = MC</span>"},{"quoi":"القاعدة","math":"كلّ نقطة متساوية البعد عن طرفي قطعة تنتمي إلى موسطها العمودي"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr\">MB = MC</span>  و  <span dir=\"ltr\" class=\"expr\">(d3)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[BC]</span>  إذن  <span dir=\"ltr\" class=\"expr\">M ∈ (d3)</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M ∈ (d3)</span>"}],
